head.script:
scwin.onpageload = function () {
    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    if (typeof target2 !== 'undefined') {
        target2.remove();
    }

    if (typeof target3 !== 'undefined') {
        target3.remove();
    }

    if (typeof paste_input !== 'undefined') {
        paste_input.remove();
    }    

    // 조건 설정   
    let properties = {        
        style: 'width:200px;height:30px;',
        disabled: true,
        preventCopyPaste: wf_sample.getObj("con_preventCopyPaste").getText(),
        initValue: "disabled=true",
    }

    let properties2 = {        
        style: 'width:200px;height:30px;',
        readOnly: true,
        preventCopyPaste: wf_sample.getObj("con_preventCopyPaste").getText(),
        initValue: "readonly=true",
    }

    let properties3 = {       
        style: 'width:200px;height:30px;',        
        preventCopyPaste: wf_sample.getObj("con_preventCopyPaste").getText(),
        initValue: "input",
    }

    let cList = $c.gcm.createCList(properties);    
    let cList2 = $c.gcm.createCList(properties2);    
    let cList3 = $c.gcm.createCList(properties3);    

    $c.gcm.createEmptyInput(cList);
    $c.gcm.createEmptyInput(cList2, '', 'target2');
    $c.gcm.createEmptyInput(cList3, '', 'target3');

    // 복사 값 붙여넣기 테스트 용  input 생성
    $c.gcm.createBasicInput('', '', 'paste_input');

    paste_input.setValue("");
}
